umns:repeat(3,1fr);gap:12px}.erp-diag .ed-health article{padding:17px;border:1px solid #dfe8ef;border-radius:12px;background:#fff}.erp-diag .ed-health article>div{display:flex;align-items:center;justify-content:space-between;gap:12px}.erp-diag .ed-health p{font-size:12px;line-height:1.7;margin-top:9px;color:#587187}.erp-diag .ed-badge{display:inline-block;border-radius:20px;font-size:10px;line-height:1.5;padding:5px 9px;font-weight:650;white-space:nowrap}.erp-diag .ed-ok{background:#eaf7ef;color:#1e7654;border-color:#c7e8d5}.erp-diag .ed-warning{background:#fff7e5;color:#875a15;border-color:#efdfb6}.erp-diag .ed-error{background:#fff0f3;color:#a52d43;border-color:#f2cfd7}.erp-diag .ed-info{background:#eaf2fd;color:#305e91;border-color:#ccdff5}.erp-diag .ed-alert{padding:15px 18px;border:1px solid #d9e5ef;border-radius:10px;line-height:1.7;margin:16px 0;font-size:13px}.erp-diag .ed-alert.ed-ok{border-color:#c7e8d5}.erp-diag .ed-alert.ed-warning{border-color:#efdfb6}.erp-diag .ed-alert.ed-error{border-color:#f2cfd7}.erp-diag .ed-alert ul{padding-left:20px;list-style:disc}.erp-diag .ed-help{font-size:11px;color:#6b8194;margin-top:12px}.erp-diag .ed-toolbar{display:flex;align-items:end;gap:12px;margin:18px 0}.erp-diag .ed-toolbar>div:first-child{flex:1}.erp-diag label{font-size:12px;display:block;font-weight:600;margin-bottom:7px;color:#4b657b}.erp-diag input:not([type=checkbox]):not([type=hidden]),.erp-diag select{display:block;width:100%;background:#fff;border:1px solid #ccdae7;padding:10px 12px;border-radius:8px;font:inherit;min-height:42px;color:#19364f}.erp-diag .ed-reset{padding:12px 4px;color:#365f8d;font-size:12px}.erp-diag .ed-incident{background:#fff;border:1px solid #dce7ef;border-radius:14px;margin-bottom:16px;overflow:hidden;box-shadow:0 2px 6px #19364f05}.erp-diag .ed-incident-top{padding:21px 23px 12px;display:flex;justify-content:space-between;align-items:start;gap:16px}.erp-diag .ed-incident-top small{display:block;color:#688196;font-size:11px}.erp-diag